from collections import deque

def solve(grid, start, goal):
    sx, sy, sz = start
    gx, gy, gz = goal

    if (sx, sy, sz) == (gx, gy, gz):
        return 0

    x_max = len(grid)
    y_max = len(grid[0])
    z_max = len(grid[0][0])

    visited = [[[False] * z_max for _ in range(y_max)] for __ in range(x_max)]
    q = deque()
    q.append((sx, sy, sz, 0))
    visited[sx][sy][sz] = True

    # All 26 possible moves: combinations of -1, 0, 1 except (0,0,0)
    directions = [
        (dx, dy, dz)
        for dx in (-1, 0, 1)
        for dy in (-1, 0, 1)
        for dz in (-1, 0, 1)
        if not (dx == 0 and dy == 0 and dz == 0)
    ]

    while q:
        x, y, z, dist = q.popleft()
        for dx, dy, dz in directions:
            nx, ny, nz = x + dx, y + dy, z + dz
            if 0 <= nx < x_max and 0 <= ny < y_max and 0 <= nz < z_max:
                if not visited[nx][ny][nz] and grid[nx][ny][nz] != -1:
                    if (nx, ny, nz) == (gx, gy, gz):
                        return dist + 1
                    visited[nx][ny][nz] = True
                    q.append((nx, ny, nz, dist + 1))

    return -1
```

