import heapq

def solve(grid, start, goal):
    sx, sy, sz = start
    gx, gy, gz = goal

    # If start and goal are the same, cost is the weight of that cell once.
    if (sx, sy, sz) == (gx, gy, gz):
        return grid[sx][sy][sz]

    x_max = len(grid)
    y_max = len(grid[0])
    z_max = len(grid[0][0])

    # Distance array, initialize with infinity
    INF = 10**18
    dist = [[[INF] * z_max for _ in range(y_max)] for __ in range(x_max)]
    dist[sx][sy][sz] = grid[sx][sy][sz]  # cost of entering start cell

    pq = [(dist[sx][sy][sz], sx, sy, sz)]

    # All 26 possible moves
    directions = [
        (dx, dy, dz)
        for dx in (-1, 0, 1)
        for dy in (-1, 0, 1)
        for dz in (-1, 0, 1)
        if not (dx == 0 and dy == 0 and dz == 0)
    ]

    while pq:
        cost, x, y, z = heapq.heappop(pq)
        if cost != dist[x][y][z]:
            continue
        # Optional early exit if we reached goal
        if (x, y, z) == (gx, gy, gz):
            return cost

        for dx, dy, dz in directions:
            nx, ny, nz = x + dx, y + dy, z + dz
            if 0 <= nx < x_max and 0 <= ny < y_max and 0 <= nz < z_max:
                weight = grid[nx][ny][nz]
                if weight == -1:  # obstacle
                    continue
                new_cost = cost + weight
                if new_cost < dist[nx][ny][nz]:
                    dist[nx][ny][nz] = new_cost
                    heapq.heappush(pq, (new_cost, nx, ny, nz))

    return -1
```

